   158  // add a word to the hash table (private)
   159  int HashMgr::add_word(const std::string& in_word,
   160                        int wcl,
   161                        unsigned short* aff,
   162                        int al,
   163                        const std::string* in_desc,
   164                        bool onlyupcase,
   165                        int captype) {
   166
   167    if (al > std::numeric_limits<short>::max()) {
   168      HUNSPELL_WARNING(stderr, "error: affix len %d is over max limit\n", al);
   169      free_flag(aff, al);
   170      return 1;
   171    }
   172
   173    const std::string* word = &in_word;
   174    const std::string* desc = in_desc;
   175
   176    std::string *word_copy = NULL;
   177    std::string *desc_copy = NULL;
   178    if ((!ignorechars.empty() && !has_no_ignored_chars(in_word, ignorechars)) || complexprefixes) {
   179      word_copy = new std::string(in_word);
   180
   181      if (!ignorechars.empty()) {
   182        if (utf8) {
   183          wcl = remove_ignored_chars_utf(*word_copy, ignorechars_utf16);
   184        } else {
   185          remove_ignored_chars(*word_copy, ignorechars);
   186        }
   187      }
   188
   189      if (complexprefixes) {
   190        if (utf8)
   191          wcl = reverseword_utf(*word_copy);
   192        else
   193          reverseword(*word_copy);
   194
   195        if (in_desc && aliasm.empty()) {
   196          desc_copy = new std::string(*in_desc);
   197
   198          if (complexprefixes) {
   199            if (utf8)
   200              reverseword_utf(*desc_copy);
   201            else
   202              reverseword(*desc_copy);
   203          }
   204          desc = desc_copy;
   205        }
   206      }
   207
   208      word = word_copy;
   209    }
   210
   211    // limit of hp->blen
   212    if (word->size() > std::numeric_limits<unsigned short>::max()) {
   213      HUNSPELL_WARNING(stderr, "error: word len %ld is over max limit\n", word->size());
   214      delete desc_copy;
   215      delete word_copy;
   216      free_flag(aff, al);
   217      return 1;
   218    }
   219
   220    bool upcasehomonym = false;
   221    int descl = desc ? (!aliasm.empty() ? sizeof(char*) : desc->size() + 1) : 0;
   222    // variable-length hash record with word and optional fields
   223    auto hp =
   224        (struct hentry*)malloc(sizeof(struct hentry) + word->size() + descl);
   225    if (!hp) {
   226      delete desc_copy;
   227      delete word_copy;
   228      free_flag(aff, al);
   229      return 1;
   230    }
   231
   232    char* hpw = hp->word;
   233    memcpy(hpw, word->data(), word->size());
   234    hpw[word->size()] = 0;
   235
   236    int i = hash(hpw, word->size());
   237
   238    hp->blen = (unsigned short)word->size();
   239    hp->clen = (unsigned short)wcl;
   240    hp->alen = (short)al;
   241    hp->astr = aff;
   242    hp->next = NULL;
   243    hp->next_homonym = NULL;
   244    hp->var = (captype == INITCAP) ? H_OPT_INITCAP : 0;
   245
   246    // store the description string or its pointer
   247    if (desc) {
   248      hp->var |= H_OPT;
   249      if (!aliasm.empty()) {
   250        hp->var |= H_OPT_ALIASM;
   251        store_pointer(hpw + word->size() + 1, get_aliasm(atoi(desc->c_str())));
   252      } else {
   253        strcpy(hpw + word->size() + 1, desc->c_str());
   254      }
   255      if (HENTRY_FIND(hp, MORPH_PHON)) {
   256        hp->var |= H_OPT_PHON;
   257        // store ph: fields (pronounciation, misspellings, old orthography etc.)
   258        // of a morphological description in reptable to use in REP replacements.
   259        size_t predicted = tableptr.size() / MORPH_PHON_RATIO;
   260        if (reptable.capacity() < predicted)
   261            reptable.reserve(predicted);
   262        std::string fields = HENTRY_DATA(hp);
   263        std::string::const_iterator iter = fields.begin(), start_piece = mystrsep(fields, iter);
   264        while (start_piece != fields.end()) {
   265          if (std::string(start_piece, iter).find(MORPH_PHON) == 0) {
   266            std::string ph = std::string(start_piece, iter).substr(sizeof MORPH_PHON - 1);
   267            if (!ph.empty()) {
   268              std::vector<w_char> w;
   269              size_t strippatt;
   270              std::string wordpart;
   271              // dictionary based REP replacement, separated by "->"
   272              // for example "pretty ph:prity ph:priti->pretti" to handle
   273              // both prity -> pretty and pritier -> prettiest suggestions.
   274              if (((strippatt = ph.find("->")) != std::string::npos) &&
   275                      (strippatt > 0) && (strippatt < ph.size() - 2)) {
   276                  wordpart = ph.substr(strippatt + 2);
   277                  ph.erase(ph.begin() + strippatt, ph.end());
   278              } else
   279                  wordpart = in_word;
   280              // when the ph: field ends with the character *,
   281              // strip last character of the pattern and the replacement
   282              // to match in REP suggestions also at character changes,
   283              // for example, "pretty ph:prity*" results "prit->prett"
   284              // REP replacement instead of "prity->pretty", to get
   285              // prity->pretty and pritiest->prettiest suggestions.
   286              if (ph.at(ph.size()-1) == '*') {
   287                strippatt = 1;
   288                size_t stripword = 0;
   289                if (utf8) {
   290                  while ((strippatt < ph.size()) &&
   291                    ((ph.at(ph.size()-strippatt-1) & 0xc0) == 0x80))
   292                       ++strippatt;
   293                  while ((stripword < wordpart.size()) &&
   294                    ((wordpart.at(wordpart.size()-stripword-1) & 0xc0) == 0x80))
   295                       ++stripword;
   296                }
   297                ++strippatt;
   298                ++stripword;
   299                if ((ph.size() > strippatt) && (wordpart.size() > stripword)) {
   300                  ph.erase(ph.size()-strippatt, strippatt);
   301                  wordpart.erase(wordpart.size()-stripword, stripword);
   302                }
   303              }
   304              // capitalize lowercase pattern for capitalized words to support
   305              // good suggestions also for capitalized misspellings, eg.
   306              // Wednesday ph:wendsay
   307              // results wendsay -> Wednesday and Wendsay -> Wednesday, too.
   308              if (captype == INITCAP) {
   309                std::string ph_capitalized;
   310                if (utf8) {
   311                  u8_u16(w, ph);
   312                  if (get_captype_utf8(w, langnum) == NOCAP) {
   313                    mkinitcap_utf(w, langnum);
   314                    u16_u8(ph_capitalized, w);
   315                  }
   316                } else if (get_captype(ph, csconv) == NOCAP)
   317                    mkinitcap(ph_capitalized, csconv);
   318
   319                if (!ph_capitalized.empty()) {
   320                  // add also lowercase word in the case of German or
   321                  // Hungarian to support lowercase suggestions lowercased by
   322                  // compound word generation or derivational suffixes
   323                  // (for example by adjectival suffix "-i" of geographical
   324                  // names in Hungarian:
   325                  // Massachusetts ph:messzecsuzec
   326                  // messzecsuzeci -> massachusettsi (adjective)
   327                  // For lowercasing by conditional PFX rules, see
   328                  // tests/germancompounding test example or the
   329                  // Hungarian dictionary.)
   330                  if (langnum == LANG_de || langnum == LANG_hu) {
   331                    std::string wordpart_lower(wordpart);
   332                    if (utf8) {
   333                      u8_u16(w, wordpart_lower);
   334                      mkallsmall_utf(w, langnum);
   335                      u16_u8(wordpart_lower, w);
   336                    } else {
   337                      mkallsmall(wordpart_lower, csconv);
   338                    }
   339                    reptable.emplace_back();
   340                    reptable.back().pattern.assign(ph);
   341                    reptable.back().outstrings[0].assign(wordpart_lower);
   342                  }
   343                  reptable.emplace_back();
   344                  reptable.back().pattern.assign(ph_capitalized);
   345                  reptable.back().outstrings[0].assign(wordpart);
   346                }
   347              }
   348              reptable.emplace_back();
   349              reptable.back().pattern.assign(ph);
   350              reptable.back().outstrings[0].assign(wordpart);
   351            }
   352          }
   353          start_piece = mystrsep(fields, iter);
   354        }
   355      }
   356    }
   357
   358    struct hentry* dp = tableptr[i];
   359    if (!dp) {
   360      tableptr[i] = hp;
   361      delete desc_copy;
   362      delete word_copy;
   363      return 0;
   364    }
   365    while (dp->next != NULL) {
   366      if ((!dp->next_homonym) && (strcmp(hp->word, dp->word) == 0)) {
   367        // remove hidden onlyupcase homonym
   368        if (!onlyupcase) {
   369          if ((dp->astr) && TESTAFF(dp->astr, ONLYUPCASEFLAG, dp->alen)) {
   370            delete[] dp->astr;
   371            dp->astr = hp->astr;
   372            dp->alen = hp->alen;
   373            free(hp);
   374            delete desc_copy;
   375            delete word_copy;
   376            return 0;
   377          } else {
   378            dp->next_homonym = hp;
   379          }
   380        } else {
   381          upcasehomonym = true;
   382        }
   383      }
   384      dp = dp->next;
   385    }
   386    if (strcmp(hp->word, dp->word) == 0) {
   387      // remove hidden onlyupcase homonym
   388      if (!onlyupcase) {
   389        if ((dp->astr) && TESTAFF(dp->astr, ONLYUPCASEFLAG, dp->alen)) {
   390          delete[] dp->astr;
   391          dp->astr = hp->astr;
   392          dp->alen = hp->alen;
   393          free(hp);
   394          delete desc_copy;
   395          delete word_copy;
   396          return 0;
   397        } else {
   398          dp->next_homonym = hp;
   399        }
   400      } else {
   401        upcasehomonym = true;
   402      }
   403    }
   404    if (!upcasehomonym) {
   405      dp->next = hp;
   406    } else {
   407      // remove hidden onlyupcase homonym
   408      delete[] hp->astr;
   409      free(hp);
   410    }
   411
   412    delete desc_copy;
   413    delete word_copy;
   414    return 0;
   415  }
