   417  int HashMgr::add_hidden_capitalized_word(const std::string& word,
   418                                           int wcl,
   419                                           unsigned short* flags,
   420                                           int flagslen,
   421                                           const std::string* dp,
   422                                           int captype) {
   423    if (flags == NULL)
   424      flagslen = 0;
   425
   426    // add inner capitalized forms to handle the following allcap forms:
   427    // Mixed caps: OpenOffice.org -> OPENOFFICE.ORG
   428    // Allcaps with suffixes: CIA's -> CIA'S
   429    if (((captype == HUHCAP) || (captype == HUHINITCAP) ||
   430         ((captype == ALLCAP) && (flagslen != 0))) &&
   431        !((flagslen != 0) && TESTAFF(flags, forbiddenword, flagslen))) {
   432      unsigned short* flags2 = new unsigned short[flagslen + 1];
   433      flags2[flagslen] = ONLYUPCASEFLAG;
   434      if (flagslen) {
   435        memcpy(flags2, flags, flagslen * sizeof(unsigned short));
   436        std::sort(flags2, flags2 + flagslen + 1);
   437      }
   438      if (utf8) {
   439        std::string st;
   440        std::vector<w_char> w;
   441        u8_u16(w, word);
   442        mkallsmall_utf(w, langnum);
   443        mkinitcap_utf(w, langnum);
   444        u16_u8(st, w);
   445        return add_word(st, wcl, flags2, flagslen + 1, dp, true, INITCAP);
   446      } else {
   447        std::string new_word(word);
   448        mkallsmall(new_word, csconv);
   449        mkinitcap(new_word, csconv);
   450        int ret = add_word(new_word, wcl, flags2, flagslen + 1, dp, true, INITCAP);
   451        return ret;
   452      }
   453    }
   454    return 0;
   455  }
