   475  // remove word (personal dictionary function for standalone applications)
   476  int HashMgr::remove(const std::string& word) {
   477    struct hentry* dp = lookup(word.c_str(), word.size());
   478    while (dp) {
   479      if (dp->alen == 0 || !TESTAFF(dp->astr, forbiddenword, dp->alen)) {
   480        auto flags = new unsigned short[dp->alen + 1];
   481        for (int i = 0; i < dp->alen; i++)
   482          flags[i] = dp->astr[i];
   483        flags[dp->alen] = forbiddenword;
   484        delete[] dp->astr;
   485        dp->astr = flags;
   486        dp->alen++;
   487        std::sort(flags, flags + dp->alen);
   488      }
   489      dp = dp->next_homonym;
   490    }
   491    return 0;
   492  }
