   494  /* remove forbidden flag to add a personal word to the hash */
   495  int HashMgr::remove_forbidden_flag(const std::string& word) {
   496    struct hentry* dp = lookup(word.c_str(), word.size());
   497    if (!dp)
   498      return 1;
   499    while (dp) {
   500      if (dp->astr && TESTAFF(dp->astr, forbiddenword, dp->alen))
   501        dp->alen = 0;  // XXX forbidden words of personal dic.
   502      dp = dp->next_homonym;
   503    }
   504    return 0;
   505  }
