   507  // add a custom dic. word to the hash table (public)
   508  int HashMgr::add(const std::string& word) {
   509    if (remove_forbidden_flag(word)) {
   510      int captype, al = 0;
   511      unsigned short* flags = NULL;
   512      int wcl = get_clen_and_captype(word, &captype);
   513      add_word(word, wcl, flags, al, NULL, false, captype);
   514      return add_hidden_capitalized_word(word, wcl, flags, al, NULL,
   515                                         captype);
   516    }
   517    return 0;
   518  }
