   520  int HashMgr::add_with_affix(const std::string& word, const std::string& example) {
   521    // detect captype and modify word length for UTF-8 encoding
   522    struct hentry* dp = lookup(example.c_str(), example.size());
   523    remove_forbidden_flag(word);
   524    if (dp && dp->astr) {
   525      int captype;
   526      int wcl = get_clen_and_captype(word, &captype);
   527      if (!aliasf.empty()) {
   528        add_word(word, wcl, dp->astr, dp->alen, NULL, false, captype);
   529      } else {
   530        auto flags = new unsigned short[dp->alen];
   531        memcpy(flags, dp->astr, dp->alen * sizeof(unsigned short));
   532        add_word(word, wcl, flags, dp->alen, NULL, false, captype);
   533      }
   534      return add_hidden_capitalized_word(word, wcl, dp->astr,
   535                                         dp->alen, NULL, captype);
   536    }
   537    return 1;
   538  }
