   540  // walk the hash table entry by entry - null at end
   541  // initialize: col=-1; hp = NULL; hp = walk_hashtable(&col, hp);
   542  struct hentry* HashMgr::walk_hashtable(int& col, struct hentry* hp) const {
   543    if (hp && hp->next != NULL)
   544      return hp->next;
   545    for (col++; col < (int)tableptr.size(); ++col) {
   546      if (tableptr[col])
   547        return tableptr[col];
   548    }
   549    // null at end and reset to start
   550    col = -1;
   551    return NULL;
   552  }
